#!/usr/bin/env python3
"""Generate Adore Shows' complete, crawlable static website."""
import json, re, html, os, sys, hashlib
from pathlib import Path
from urllib.parse import quote, urlsplit
from home_design import build_home, build_story, build_contact
from about_content import build_about
from gospel_content import gospel_guide, gospel_faq
from municipal_content import municipal_feature
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs'
PRODUCTION='--production' in sys.argv
ORIGIN=os.environ.get('SITE_URL','https://felipercmb.github.io/adore-shows').rstrip('/')
BASE_PATH=urlsplit(ORIGIN).path.rstrip('/')
A=json.loads((ROOT/'data/artists.json').read_text())
BY={a['slug']:a for a in A}
G={'sertanejo':'Sertanejo','forro':'Forró','gospel':'Gospel','samba-e-pagode':'Samba e pagode','catolico':'Católico','axe':'Axé','mpb':'MPB','rock':'Rock','pregadores':'Pregadores','internacional':'Internacional'}
ORDER=['gusttavo-lima','aline-barros','wesley-safadao','lauana-prado','thiaguinho','fernandinho','joao-gomes','gabriela-rocha','juliano-son','padre-fabio-de-melo','jorge-matheus','titas','ana-carolina']
A=sorted(A,key=lambda a: ORDER.index(a['slug']) if a['slug'] in ORDER else 1000)
WA='https://wa.me/5562985450777'
E=html.escape
URLS=[]
def asset(path):
 return path+'?v='+hashlib.sha256((OUT/path.lstrip('/')).read_bytes()).hexdigest()[:12]
def icon(n='arrow'):
 p={'arrow':'<path d="M5 12h14M13 6l6 6-6 6"/>','diagonal':'<path d="M6 18 18 6M6 6h12v12"/>','search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>','down':'<path d="M12 4v16m-6-6 6 6 6-6"/>','menu':'<path d="M4 8h16M4 16h16"/>','music':'<path d="M9 18V5l11-2v13M9 9l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2.5"/><ellipse cx="17" cy="16" rx="3" ry="2.5"/>','building':'<path d="M3 21h18M6 21V8h12v13M4 8l8-5 8 5M9 12v5M15 12v5"/>','heart':'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>','mic':'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>','phone':'<path d="M6 3h4l1 5-3 2a15 15 0 0 0 6 6l2-3 5 1v4a3 3 0 0 1-3 3A18 18 0 0 1 3 6a3 3 0 0 1 3-3Z"/>','mail':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>','play':'<path d="m9 5 11 7-11 7Z"/>'}
 return '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+p[n]+'</svg>'
def photo(a):
 local=a.get('localImage','')
 if local and (OUT/local.lstrip('/')).is_file():return local
 return '/assets/artist-placeholder.svg'
def button(text,url,style='',ic='arrow'):
 return f'<a class="button {style}" href="{E(url,quote=True)}">{E(text)}{icon(ic)}</a>'
def header(current=''):
 links=[('Artistas','/artistas/'),('Prefeituras','/#prefeituras'),('A Adore','/quem-somos/'),('Como contratar','/#como-contratar')]
 return f'''<a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="header"><nav class="nav wrap" aria-label="Navegação principal"><a href="/" class="logo" aria-label="Adore Shows, início"><img src="/assets/logo.png" alt="Adore Shows" width="1959" height="211"></a><button class="menu-button" aria-label="Abrir menu" aria-controls="nav-links" aria-expanded="false">{icon('menu')}</button><div class="nav-links" id="nav-links">{''.join(f'<a href="{u}"'+(' aria-current="page"' if current==u else '')+f'>{t}</a>' for t,u in links)}{button('Vamos fazer um show','/contrate/','small','diagonal')}</div></nav></header>'''
def footer():
 return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="logo" href="/" aria-label="Adore Shows, início"><img src="/assets/logo.png" width="1959" height="211" alt="Adore Shows" style="width:210px"></a><p>Grandes artistas. Encontros que ficam.<br>De Goiânia para os palcos de todo o Brasil.</p></div><div><h3>Encontre seu próximo show</h3><div class="footer-links"><a href="/#prefeituras">Shows para prefeituras</a><a href="/artistas/">Explore os artistas</a><a href="/quem-somos/">Conheça a Adore</a><a href="/contrate/">Contrate um artista</a><a href="/seja-artista/">Sou artista</a></div></div><div><h3>Fale com a nossa equipe</h3><div class="footer-links"><a class="footer-contact" href="{WA}">(62) 98545-0777</a><a href="mailto:shows@adoreshows.com">shows@adoreshows.com</a><span class="footer-location">Goiânia, Goiás · Brasil</span><a href="https://www.instagram.com/adoreshowsbrasil/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://www.facebook.com/adoreshows/" target="_blank" rel="noopener noreferrer">Facebook</a></div></div></div><div class="footer-giant" aria-hidden="true">ADORE SHOWS</div><div class="footer-base"><span>© 2026 Adore Eventos Ltda. Todos os direitos reservados.</span><span>Agenciamento artístico com atuação nacional</span><a href="/privacidade/">Privacidade</a></div></div></footer>'''
ORG={'@type':'Organization','@id':ORIGIN+'/#organization','name':'Adore Shows','url':ORIGIN+'/','logo':ORIGIN+'/assets/logo.png','description':'Agência de artistas em Goiânia, Goiás. Contratação de shows para prefeituras, produtores, igrejas e empresas em todo o Brasil.','telephone':'+5562985450777','email':'shows@adoreshows.com','address':{'@type':'PostalAddress','addressLocality':'Goiânia','addressRegion':'GO','addressCountry':'BR'},'areaServed':{'@type':'Country','name':'Brasil'},'sameAs':['https://www.instagram.com/adoreshowsbrasil/','https://www.facebook.com/adoreshows/']}
def page(path,title,description,body,current='',image='/assets/hero/titas-live.jpg',schema=None):
 canonical=ORIGIN+path
 graph=[ORG,{'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'description':description,'inLanguage':'pt-BR','isPartOf':{'@id':ORIGIN+'/#website'}}]
 if path=='/':graph.append({'@type':'WebSite','@id':ORIGIN+'/#website','url':ORIGIN+'/','name':'Adore Shows','inLanguage':'pt-BR','publisher':{'@id':ORIGIN+'/#organization'}})
 if schema:graph.extend(schema)
 doc=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b0c"><title>{E(title)}</title><meta name="description" content="{E(description,quote=True)}"><meta name="robots" content="{'index,follow' if PRODUCTION and path!='/404/' else 'noindex,nofollow'}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="Adore Shows"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN+image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/bricolage-grotesque-variable.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="{asset('/assets/site.css')}"><link rel="stylesheet" href="{asset('/assets/live.css')}"><link rel="stylesheet" href="{asset('/assets/refinements.css')}"><link rel="stylesheet" href="{asset('/assets/sound-cta.css')}"><link rel="stylesheet" href="{asset('/assets/hero.css')}"><link rel="stylesheet" href="{asset('/assets/about.css')}"><link rel="stylesheet" href="{asset('/assets/municipal.css')}"><noscript><style>@media(max-width:800px){{.header{{height:auto;padding-bottom:20px}}.site-home .header{{position:relative;inset:auto}}.nav{{height:auto;min-height:60px;flex-wrap:wrap;padding:18px 23px;border-radius:30px}}.menu-button{{display:none}}.nav-links{{display:flex;position:static;flex-basis:100%;max-height:none;overflow:visible;padding:8px 0 0;border:0;background:transparent}}.nav-links a:not(.button){{padding:8px 0}}.nav-links .button{{width:fit-content;margin-top:4px}}}}</style></noscript><script defer src="{asset('/assets/site.js')}"></script><script defer src="{asset('/assets/motion.js')}"></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')}</script></head><body class="{'site-home' if path=='/' else 'site-inner'}">{header(current)}<main id="conteudo">{body}</main>{footer()}</body></html>'''
 doc=doc.replace('<head>',f'<head><meta name="site-base" content="{E(BASE_PATH,quote=True)}">',1)
 doc=re.sub(r'\b(href|src|poster|action)="/(?!/)',lambda m:m.group(1)+'="'+BASE_PATH+'/',doc)
 target=OUT/path.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc)
 URLS.append(canonical)
def crumb(items):
 return '<nav class="breadcrumb" aria-label="Caminho da página"><a href="/">Início</a>'+''.join(f'<span aria-hidden="true">/</span><a href="{u}">{E(t)}</a>' if u else f'<span aria-hidden="true">/</span><span aria-current="page">{E(t)}</span>' for t,u in items)+'</nav>'
def card(a):
 return f'''<a class="artist-card" href="/{a['slug']}/"><div class="artist-photo"><img src="{photo(a)}" alt="{E(a['name'],quote=True)}" width="640" height="800" loading="lazy" decoding="async"><span class="card-arrow">{icon('diagonal')}</span></div><div class="artist-info"><h3>{E(a['name'])}</h3><small>{E(G.get(a['genre'],a['genre']))}</small></div></a>'''
def catalog(genre='',home=False):
 selected=[a for a in A if not genre or genre in a['genres']]
 count=6 if home else (12 if genre=='gospel' else 24)
 filters='<a class="filter '+('active' if not genre else '')+'" href="/artistas/" data-genre=""'+(' aria-current="true"' if not genre else '')+'>Todos <small>500</small></a>'
 for g,label in G.items():
  total=sum(g in a['genres'] for a in A)
  filters+=f'<a class="filter {"active" if genre==g else ""}" href="/artistas/{g}/" data-genre="{g}"'+(' aria-current="true"' if genre==g else '')+f'>{label} <small>{total}</small></a>'
 return f'''<div class="catalog {'is-curated' if home else ''}" data-catalog data-genre="{genre}" data-limit="{count}"><div class="catalog-tools"><div class="search-box">{icon('search')}<label class="sr-only" for="artist-search" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Buscar artista pelo nome</label><input id="artist-search" type="search" placeholder="Quem você quer no seu palco?" autocomplete="off" maxlength="100"></div><p class="catalog-caption" id="catalog-status" role="status" aria-live="polite">{len(selected)} artistas · {min(count,len(selected))} em exibição</p></div><nav class="filters" aria-label="Filtrar artistas por segmento">{filters}</nav><div class="artist-grid" id="artist-grid">{''.join(card(a) for a in selected[:count])}</div><div class="catalog-bottom"><button class="button light-outline" id="load-more" type="button" {'hidden' if len(selected)<=count else ''}>Mostrar mais artistas {icon('down')}</button><a class="text-link" href="/contrate/">Precisa de ajuda para escolher? {icon('diagonal')}</a></div><p class="catalog-disclaimer">Consulte disponibilidade e condições de contratação. A presença no catálogo não implica representação exclusiva do artista.</p><noscript><p class="no-script">Para explorar sem JavaScript, escolha um segmento acima ou consulte a <a href="/todos-os-artistas/">lista completa de artistas</a>.</p></noscript></div>'''
FAQ=[
 ('Como consultar shows para uma prefeitura?', 'Informe o município, a data, a programação prevista e os artistas ou estilos desejados. A Adore consulta a agenda e apresenta as condições da atração para que a equipe responsável avalie a proposta. Aniversários da cidade, festas populares e festivais podem fazer parte dessa conversa.'),
 ('Quais estilos musicais a Adore atende?', 'O catálogo reúne sertanejo, forró, gospel, samba e pagode, música católica, axé, MPB, rock e outros segmentos. Escolha os nomes que combinam com sua programação ou peça sugestões à equipe.'),
 ('Quanto custa contratar um show?', 'O valor depende do artista, da data, da cidade e das condições da apresentação. Compartilhe os detalhes do evento para receber uma proposta e confira com a equipe quais itens estão incluídos.'),
 ('A Adore Shows atende fora de Goiânia?', 'Sim. Nossa agência é de Goiânia, Goiás, e atende contratantes de todo o Brasil. Informe a cidade do evento para consultar disponibilidade, deslocamento e condições de apresentação.'),
 ('Ainda não escolhi o artista. Vocês podem ajudar?', 'Sim. Conte quem é o seu público, qual é a proposta do evento e quais estilos você procura. Nossa equipe ajuda a avaliar as opções do catálogo, sempre mediante consulta de disponibilidade.')]

def faq():return '<section class="faq section"><div class="wrap faq-grid"><h2>Antes de abrir<br>as cortinas.</h2><div>'+''.join(f'<details><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in FAQ)+'</div></div></section>'
def contact():return build_contact(icon)
def process():return f'''<section class="section" id="como-contratar"><div class="wrap process"><div class="process-intro"><h2>Você imagina.<br>A gente conecta.</h2><p>De uma festa municipal a um festival, evento de igreja ou celebração privada, a escolha começa pelo público. A equipe da Adore acompanha as decisões da contratação.</p><a class="text-link" href="/contrate/">Vamos conversar {icon('diagonal')}</a></div><ol class="steps"><li><div><h3>Conte o que está planejando</h3><p>Conte a data, a cidade, o público estimado e o formato do evento: aniversário do município, festa popular, festival ou outra programação. Informe também os estilos desejados e a faixa de investimento, se já estiver definida.</p></div></li><li><div><h3>Conheça as possibilidades</h3><p>Consultamos a disponibilidade e as condições da apresentação para preparar uma proposta alinhada ao seu evento.</p></div></li><li><div><h3>Combine cada detalhe</h3><p>Com a proposta definida, alinhamos as condições e os próximos passos da contratação com você.</p></div></li></ol></div></section>'''
services=[
 ('building','Prefeituras e festas municipais','Artistas para aniversários de cidades, festas populares e festivais. A equipe consulta atrações conforme a data, o perfil do público e a programação do município.'),
 ('heart','Igrejas e eventos religiosos','Cantores, bandas e ministérios gospel e católicos para congressos, encontros de louvor e celebrações, com consulta de agenda e condições de apresentação.'),
 ('mic','Produtores e eventos corporativos','Artistas para festivais, convenções e confraternizações. Conte o formato e os estilos desejados para avaliar as possibilidades.'),
 ('music','Festas e eventos privados','Atrações para festas e celebrações particulares. Um catálogo de diferentes estilos para encontrar o nome que combina com seus convidados.')]

def story():return build_story(icon,services)
gospel_count=sum('gospel' in a['genres'] for a in A)
home=build_home(button,icon,catalog,story,process,faq,contact,lambda:municipal_feature(icon))
page('/','Shows para Prefeituras e Eventos | Adore Shows','Contratação de shows para prefeituras, festas municipais, festivais, igrejas e empresas. Consulte artistas de diferentes estilos com a Adore Shows. Atendimento nacional.',home,image='/assets/hero/titas-live.jpg')
for g in ['',*G]:
 label=G.get(g,'Artistas')
 title='Um país de vozes.\nO seu próximo show.' if not g else {'gospel':'Cantores gospel para\no seu próximo encontro.','sertanejo':'Histórias para cantar\na uma só voz.','forro':'O encontro tem ritmo.\nO palco tem forró.'}.get(g,f'{label}.\nUm encontro para lembrar.')
 segment={'catolico':'artistas católicos','internacional':'artistas internacionais','pregadores':'pregadores'}.get(g,f'artistas de {label.lower()}' if g else 'artistas em 10 segmentos')
 intro=f'Explore {sum(g in a["genres"] for a in A) if g else len(A)} {segment} e consulte disponibilidade para o seu evento. Atendimento em Goiânia e em todo o Brasil.'
 path=f'/artistas/{g}/' if g else '/artistas/'
 body=f'<section class="section page-top"><div class="wrap">{crumb([("Artistas","/artistas/") ,(label,"")]) if g else crumb([("Artistas","")])}<div class="page-heading"><h1 class="page-title">{E(title).replace(chr(10),"<br>")}</h1><p class="page-description">{intro}</p></div>{catalog(g)}</div></section>{contact()}'
 if g=='gospel':
  intro=f'Encontre cantores e bandas gospel para a programação da sua igreja, congresso ou festival. A Adore reúne {gospel_count} artistas do segmento para consulta de disponibilidade e contratação. Escolha um nome ou conte à equipe o perfil do seu evento.'
  body=f'<section class="section page-top gospel-category"><div class="wrap">{crumb([("Artistas","/artistas/"),(label,"")])}<div class="page-heading"><h1 class="page-title">{E(title).replace(chr(10),"<br>")}</h1><p class="page-description">{intro}</p>{button("Consultar um show gospel","/contrate/?segmento=gospel","dark")}<a class="text-link gospel-guide-link" href="#gospel-guide-title">Ver etapas da contratação {icon("down")}</a></div>{catalog(g)}</div></section>{gospel_guide(icon)}{gospel_faq()}{contact()}'
  page(path,'Contratar Cantores e Shows Gospel | Adore Shows','Consulte cantores e bandas gospel para igrejas, congressos e festivais. A Adore Shows atende em todo o Brasil, com agência em Goiânia.',body,'/artistas/',image='/assets/hero/aline-barros.webp',schema=[{'@type':'Service','name':'Contratação de shows gospel','serviceType':'Agenciamento e contratação de artistas gospel','provider':{'@id':ORIGIN+'/#organization'},'areaServed':{'@type':'Country','name':'Brasil'},'url':ORIGIN+path}])
 else:
  page(path,f'{label} para seu evento | Adore Shows',intro,body,'/artistas/')
for a in A:
 slug=a['slug'];name=a['name'];genre=G[a['genre']]
 rawbio=a.get('bio','').strip()
 # Keep source prose while avoiding unsupported rewriting of artist biographies.
 paras=[x.strip() for x in re.split(r'\n\s*\n',rawbio) if x.strip()]
 bio=''.join('<p>'+E(p)+'</p>' for p in paras[:4])
 if not bio:bio=f'<p>{E(name)} integra o catálogo de {genre.lower()} da Adore Shows. Fale com a nossa equipe para conhecer as condições de apresentação no seu evento.</p>'
 videos=[v for v in a.get('videos',[]) if re.fullmatch(r'[A-Za-z0-9_-]{11}',v)]
 vhtml='<div class="video-links">'+''.join(f'<a class="text-link" href="https://www.youtube.com/watch?v={v}" target="_blank" rel="noopener noreferrer">{icon("play")} Ver apresentação'+(f' {i+1}' if len(videos)>1 else '')+'</a>' for i,v in enumerate(videos[:2]))+'</div>' if videos else ''
 rel=[x for x in A if x['slug']!=slug and a['genre'] in x['genres']][:4]
 description=(f'Contratar {name} para seu evento gospel? Consulte agenda, proposta e condições com a Adore Shows. Atendimento em Goiânia e todo o Brasil.' if 'gospel' in a['genres'] else f'Quer contratar {name}? Consulte disponibilidade, proposta e condições com a Adore Shows. Agência de artistas em Goiânia com atuação nacional.')
 body=f'''<div class="wrap page-top">{crumb([('Artistas','/artistas/'),(genre,f'/artistas/{a["genre"]}/'),(name,'')])}<section class="profile"><img class="profile-image" src="{photo(a)}" alt="{E(name,quote=True)}" width="640" height="800" fetchpriority="high"><div class="profile-content"><a class="genre-tag" href="/artistas/{a['genre']}/">{genre}</a><h1>{E(name)}</h1><p class="profile-lead">Quer {E(name)} no seu evento? Conte a data, a cidade e o que você está planejando. A Adore consulta a disponibilidade e prepara os próximos passos.</p>{button('Consultar disponibilidade','/contrate/?artista='+quote(name),'dark')}<p class="profile-note">Atendimento em todo o Brasil. Proposta mediante consulta.</p><h2>Conheça {E(name)}</h2><div class="bio">{bio}</div>{vhtml}</div></section></div><section class="section" style="background:#e7ece8"><div class="wrap"><div class="section-head"><h2>Outros encontros possíveis.</h2><a class="text-link" href="/artistas/{a['genre']}/">Ver {genre.lower()} {icon('arrow')}</a></div><div class="artist-grid">{''.join(card(x) for x in rel)}</div></div></section>{contact()}'''
 page('/'+slug+'/',f'Contratar {name} | Shows e contato — Adore Shows',description,body,'/artistas/',image=photo(a),schema=[{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Artistas','item':ORIGIN+'/artistas/'},{'@type':'ListItem','position':2,'name':name,'item':ORIGIN+'/'+slug+'/'}]}])
about=build_about(crumb,button,icon,contact,len(A))
page('/quem-somos/','A Adore Shows | Agenciamento de Artistas e Contratação de Shows','Conheça a Adore Shows: mais de 15 anos no agenciamento de artistas e contratação de shows para prefeituras, produtores, igrejas e empresas de todo o Brasil.',about,'/quem-somos/',image='/assets/hero/titas-live.jpg',schema=[{'@type':'AboutPage','@id':ORIGIN+'/quem-somos/#webpage','about':{'@id':ORIGIN+'/#organization'}}])
form=f'''<section class="section page-top"><div class="wrap">{crumb([('Contrate um artista','')])}<div class="form-layout"><div class="form-intro"><h1>Todo grande show<br>começa com<br>uma conversa.</h1><p>Organiza uma festa da cidade, um festival ou outro evento? Conte a data, a cidade e a atração desejada. Atendemos prefeituras, produtores, igrejas e empresas, com propostas conforme a programação e o público.</p><div class="contact-options"><a href="{WA}">{icon('phone')} (62) 98545-0777</a><a href="mailto:shows@adoreshows.com">{icon('mail')} shows@adoreshows.com</a></div><p>Goiânia, Goiás. Atendimento em todo o Brasil.<br>Segunda a sexta, das 9h às 18h.</p></div><form class="brief-form" id="event-form"><fieldset id="form-fields" disabled style="border:0;margin:0;padding:0;min-width:0"><legend style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Dados para o orçamento</legend><h2 class="form-heading">Vamos conhecer seu evento</h2><div class="field"><label for="name">Seu nome *</label><input id="name" name="name" autocomplete="name" required maxlength="100" placeholder="Como podemos chamar você?"></div><div class="field"><label for="organization">Prefeitura, empresa ou instituição</label><input id="organization" name="organization" autocomplete="organization" maxlength="150" placeholder="Quem está organizando o evento? (opcional)"></div><div class="field"><label for="artist">Artista que você tem em mente</label><input id="artist" name="artist" maxlength="150" placeholder="Um nome, um estilo ou deixe com a gente"></div><div class="form-row"><div class="field"><label for="city">Cidade e estado *</label><input id="city" name="city" required maxlength="120" placeholder="Ex.: Goiânia, GO"></div><div class="field"><label for="date">Data prevista</label><input id="date" name="date" type="date"></div></div><div class="field"><label for="event-type">Tipo de evento *</label><select id="event-type" name="type" required><option value="">Selecione uma opção</option><option>Festa municipal ou festival</option><option>Evento gospel ou encontro de louvor</option><option>Evento católico</option><option>Evento corporativo</option><option>Festa ou evento privado</option><option>Outro tipo de evento</option></select></div><div class="field"><label for="message">Conte um pouco mais</label><textarea id="message" name="message" maxlength="1500" placeholder="Público estimado, proposta do evento, referências…"></textarea></div><button class="button dark" type="submit">Preparar pedido no WhatsApp {icon('arrow')}</button><p class="form-disclosure">Seu pedido será preparado aqui. Você poderá revisar e enviar a mensagem no WhatsApp. Este formulário não armazena os dados no site. <a href="/privacidade/">Saiba mais sobre privacidade.</a></p><div class="form-result" id="form-result" hidden role="status"><p>Seu pedido está pronto. Abra o WhatsApp para revisar a mensagem e enviá-la à equipe da Adore.</p><a class="button dark" id="whatsapp-request" target="_blank" rel="noopener noreferrer">Abrir pedido no WhatsApp {icon('diagonal')}</a></div><noscript><p class="form-disclosure">Use o <a href="{WA}">WhatsApp direto</a> para informar nome, artista, cidade e data do evento.</p></noscript></fieldset></form></div></div></section>{faq()}'''
page('/contrate/','Contrate um Artista | Orçamento de Shows — Adore Shows','Solicite proposta para contratação de artistas com a Adore Shows. Informe cidade, data e perfil do evento. Atendimento em Goiânia e todo o Brasil.',form)
artist_page=f'''<section class="section page-top"><div class="wrap">{crumb([('Sou artista','')])}<div class="form-layout"><div class="form-intro"><h1>Sua música.<br>Novos encontros.</h1><p>Quer apresentar seu trabalho à Adore Shows? Nossa representação exclusiva é voltada a artistas e ministérios gospel e católicos. Para outros gêneros, trabalhamos com contratação de shows sob demanda.</p><p>Envie seu material para a equipe conhecer sua trajetória, seu repertório e o momento da sua carreira.</p>{button('Apresente seu trabalho',WA+'?text='+quote('Olá, equipe Adore Shows! Sou artista e gostaria de apresentar meu trabalho.'),'dark')}<p>O contato inicial é uma apresentação. A equipe avalia o material e conversa sobre as possibilidades de trabalho.</p></div><div><h2 class="section-title">Conte a sua história.</h2><ol class="steps" style="margin-top:35px"><li><div><h3>Apresente seu projeto</h3><p>Nome artístico, cidade, segmento musical e um breve resumo da sua trajetória.</p></div></li><li><div><h3>Mostre sua música</h3><p>Links de apresentações ao vivo, redes sociais e lançamentos ajudam a conhecer seu trabalho.</p></div></li><li><div><h3>Vamos conversar</h3><p>Inclua um contato profissional para que a equipe possa retornar sobre o material enviado.</p></div></li></ol></div></div></div></section>'''
page('/seja-artista/','Apresente seu Trabalho | Artistas — Adore Shows','Apresente seu projeto artístico à Adore Shows. Envie trajetória, links de apresentações e contato profissional para avaliação da equipe.',artist_page)
privacy=f'''<section class="section page-top"><div class="wrap">{crumb([('Privacidade','')])}<article class="article"><h1>Privacidade, com clareza.</h1><p>Esta versão do site da Adore Shows apresenta artistas e facilita o contato com nossa equipe.</p><h2>Informações do seu pedido</h2><p>O formulário prepara uma mensagem no seu navegador. Os campos não são enviados nem armazenados por um servidor deste site. A mensagem é compartilhada com a Adore Shows quando você abre o WhatsApp e decide enviá-la.</p><h2>Serviços externos</h2><p>Ao acessar WhatsApp, Instagram, Facebook ou YouTube, você passa a usar serviços com suas próprias políticas de privacidade. Vídeos não são carregados automaticamente neste site.</p><h2>Cookies e navegação</h2><p>Este código não instala ferramentas de publicidade, rastreamento ou análise e não grava os campos de formulário em cookies ou armazenamento local. A hospedagem pode processar dados técnicos necessários para entregar e proteger as páginas.</p><h2>Fale com a Adore</h2><p>Para dúvidas sobre as informações compartilhadas no atendimento, entre em contato pelo <a href="mailto:shows@adoreshows.com">shows@adoreshows.com</a> ou <a href="{WA}">(62) 98545-0777</a>.</p></article></div></section>'''
page('/privacidade/','Privacidade | Adore Shows','Saiba como o site da Adore Shows prepara seu pedido e facilita o contato com a equipe.',privacy)
allbody='<section class="section"><div class="wrap">'+crumb([('Todos os artistas','')])+'<h1 class="page-title">Todos os artistas.</h1><div class="no-script" style="margin-top:30px">'+''.join(f'<a href="/{a["slug"]}/">{E(a["name"])}</a>' for a in sorted(A,key=lambda a:a['name']))+'</div></div></section>'
page('/todos-os-artistas/','Todos os 500 Artistas | Adore Shows','Lista completa dos artistas do catálogo Adore Shows, com links para perfis e consulta de contratação.',allbody)
notfound='<section class="section"><div class="wrap"><h1 class="page-title">Esse palco mudou<br>de endereço.</h1><p class="page-description">Não encontramos a página que você procura. Explore o catálogo para encontrar seu artista.</p><div style="margin-top:32px">'+button('Explorar os artistas','/artistas/','dark')+'</div></div></section>'
