compact=[{'name':a['name'],'slug':a['slug'],'genre':a['genre'],'genres':a['genres'],'image':photo(a)} for a in A]
(OUT/'assets/catalog.json').write_text(json.dumps(compact,ensure_ascii=False,separators=(',',':')))
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in URLS if '/404/' not in u)+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n' if PRODUCTION else 'Disallow: /\n'))
(OUT/'.nojekyll').touch()
print(f'Built {len(URLS)} complete static pages, {len(A)} artists; indexing={"enabled" if PRODUCTION else "disabled"}.')
